# ---------------- writer ----------------
os.makedirs(OUT, exist_ok=True)
assert len(D) == 60, len(D)
cnt = dict(changed_main=0, reserve_used=0, disputed=0)
sizes = []
for cid, v in D.items():
    doc = {"case_id": cid, "prediction_text": v["prediction_text"], "basis": v["basis"],
           "confidence": v["confidence"], "trigger": v["trigger"]}
    p = os.path.join(OUT, cid + ".json")
    with open(p, "w", encoding="utf-8") as f:
        json.dump(doc, f, ensure_ascii=False, indent=1)
    for k in cnt:
        if v["trigger"][k]: cnt[k] += 1
    sizes.append((p, os.path.getsize(p)))
print("written", len(sizes))
print("trigger counts", cnt)
for p, s in sizes:
    print(p, s)
